args.query:
select login,fio,role,company_inn from api.app_user;
select * from api.company;
select rolname from pg_roles where rolname !~ '^pg_';
\d api.app_user
\d api.application
select policyname,tablename,roles,cmd,qual,with_check from pg_policies;
select pg_get_viewdef('api.company'::regclass);
select pg_get_viewdef('api.limit_balance'::regclass);

select proname,prosrc from pg_proc where proname in ('my_company','app_company');
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema='api' and grantee in ('applicant','anon');
select conname,pg_get_constraintdef(oid) from pg_constraint where conrelid in ('api.app_user'::regclass,'api.application'::regclass);

update api.app_user set role='applicant', company_inn='7700004036' where login='delta_user';
select grantee,column_name,privilege_type from information_schema.column_privileges where table_schema='api' and table_name='application' and grantee='applicant';
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema='api' and table_name in ('limit_balance','app_user') ;
